ValidationRule.errorConditionFormula:
AND(
  OR(
    ISCHANGED(Checker_Comments__c),
    ISCHANGED(Checker_Result__c),
    ISCHANGED(Checker_Result_Date_Time__c)
  ),
  NOT(
    OR(
      Owner:Queue.Name = "UAR Checker",
      AND(
        Previous_Owner_Queue__c = "UAR Checker",
        ISCHANGED(OwnerId)
      )
    )
  )
)
